"""Roda o bot real (run_scenarios.py), grava output/ e gera a demo. 'recorded' = última mensagem de cada conversa, com as anteriores em 'before' (estado persiste)."""
import pathlib, sys
HERE = pathlib.Path(__file__).parent; sys.path.insert(0, str(HERE)); sys.path.insert(0, str(HERE.parent / "_demo" / "tools"))
import run_scenarios
from dl import *
SLUG = "30-bot-telegram-discord-demo"; R = run_scenarios.main()
recorded = [{"fresh": True, "before": [x["input"] for x in R[k][:-1]], "input": R[k][-1]["input"], "expect": {"route": R[k][-1]["route"], "payload": R[k][-1]["payload"]}} for k in run_scenarios.SCEN]
logic = (HERE / "demo_logic.js").read_text("utf-8")
nodes = [("start", "Webhook update", "webhook", 0, 0, B("evento no formato da plataforma", "event in the platform's format")), ("normalize", "Normalize", "code", 1, 0, B("Telegram e Discord viram 1 formato", "Telegram and Discord become 1 format")), ("bot", "Bot router", "switch", 2, 1, B("limite · comando · conversa · admin", "limit · command · flow · admin")),
         ("guard", "Guard", "if", 3, 0, B("limite de msgs ou só admin", "message limit or admin-only")), ("command", "Command", "code", 3, 1, B("/pedido /estoque /ajuda", "/pedido /estoque /ajuda")), ("flow", "Guided flow", "memory", 3, 2, B("/novo em etapas", "/novo in steps")),
         ("unknown", "Fallback", "set", 3, 3, B("não entendi + ajuda", "didn't get it + help")), ("send", "Reply payload", "http", 4, 1, B("sendMessage / create message (não enviado)", "sendMessage / create message (not sent)"))]
edges = [{"from": "start", "to": "normalize"}, {"from": "normalize", "to": "bot"}] + [{"from": "bot", "to": b, "when": b, "label": b} for b in ("guard", "command", "flow", "unknown")] + [{"from": b, "to": "send"} for b in ("guard", "command", "flow", "unknown")]
P = lambda pt, en, plat, user, text, gap="3": {"label": B(pt, en), "values": {"platform": plat, "user": user, "text": text, "gap": gap}}
cfg = {"slug": SLUG, "title": B("Bot de atendimento para Telegram e Discord (modo demo)", "Support bot for Telegram and Discord (demo mode)"), "tag": B("Python · bot · Telegram · Discord", "Python · bot · Telegram · Discord"),
 "summary": B("Um bot que consulta pedido e estoque, conduz um pedido em etapas, barra flood e separa comandos de administrador. Recebe o evento no formato real do Telegram ou do Discord e devolve o payload que seria enviado. Sem token e sem rede: é um modo demo, não um bot no ar.",
              "A bot that looks up orders and stock, walks a user through a new order in steps, blocks flooding and keeps admin commands separate. It takes the event in the real Telegram or Discord format and returns the payload that would be sent. No token, no network: it is a demo mode, not a live bot."),
 "input": {"nosim": True, "trigger": B("python bot.py (conversa de exemplo, sem rede)", "python bot.py (sample conversation, no network)"),
  "note": B("A conversa continua entre as execuções, como num chat: rode /novo e depois responda item, quantidade e sim. Mande 6 mensagens com 0.5 s de intervalo para ver o limite. Ana (111) é cliente; Bruno (222) é administrador.", "The conversation carries over between runs, like a chat: run /novo and then answer item, quantity and yes. Send 6 messages 0.5 s apart to see the rate limit. Ana (111) is a customer; Bruno (222) is an admin."),
  "presets": [P("1. Meu pedido", "1. My order", "telegram", "111", "/pedido 1042"), P("2. Pedido de outra pessoa", "2. Someone else's order", "telegram", "111", "/pedido 2001"), P("3. Começar um pedido", "3. Start an order", "telegram", "111", "/novo"), P("4. Discord: texto solto", "4. Discord: loose text", "discord", "222", "oi, tudo bem?"), P("5. Admin sem permissão", "5. Admin without permission", "telegram", "111", "/admin_resumo")],
  "fields": [sel("platform", [("telegram", B("Telegram", "Telegram")), ("discord", B("Discord", "Discord"))], B("Plataforma", "Platform")), sel("user", [("111", B("Ana (cliente)", "Ana (customer)")), ("222", B("Bruno (administrador)", "Bruno (admin)"))], B("Quem escreve", "Who writes")),
             txt("text", "/pedido 1042", B("Mensagem", "Message")), txt("gap", "3", B("Segundos desde a anterior", "Seconds since the previous one"))]},
 "nodes": nodes_of(nodes), "edges": edges,
 "case": {"problem": B("Perguntas repetidas de cliente (\"onde está meu pedido?\", \"tem em estoque?\") tomam o tempo de quem atende, e um bot feito às pressas ou vaza dado de outro cliente ou aceita qualquer comando.", "Repeated customer questions (\"where is my order?\", \"is it in stock?\") eat the support team's time, and a hastily built bot either leaks another customer's data or accepts any command."),
  "solution": B("Um roteador pequeno: o evento é normalizado, passa pelo limite de mensagens, e cai em comando, conversa em etapas, comando de administrador (lista fixa) ou resposta de ajuda. Pedido de outra pessoa responde igual a pedido inexistente. A resposta sai no formato de cada plataforma.", "A small router: the event is normalized, passes the rate limit and lands on a command, a stepped conversation, an admin command (fixed list) or a help reply. Someone else's order gets the same answer as a missing one. The reply goes out in each platform's format."),
  "gain": B("Estimativa, não medição: se 30 perguntas simples por dia levam ~2 min cada, são ~1 h de atendimento por dia que o bot absorve. Isso supõe perguntas repetitivas e uma base de pedidos acessível; o que foge do roteiro continua indo para uma pessoa.", "An estimate, not a measurement: if 30 simple questions a day take ~2 min each, that is ~1 h of support a day the bot absorbs. It assumes repetitive questions and an accessible orders base; anything off-script still goes to a person."),
  "stack": ["Python 3.13", "re", "Telegram Bot API (formato)", "Discord API (formato)"],
  "run": {"title": B("Como rodar", "How to run"), "steps": B(["python bot.py (conversa de exemplo no terminal)", "python run_scenarios.py (5 conversas → output/)", "Testes: python tests/test_bot.py"], ["python bot.py (sample conversation in the terminal)", "python run_scenarios.py (5 conversations → output/)", "Tests: python tests/test_bot.py"]),
          "files": [{"href": "bot.py", "label": B("Baixar bot.py", "Download bot.py")}]},
  "honesty": B("O código é o bot.py portado para JavaScript e conferido contra as saídas gravadas do Python. Os eventos têm o formato dos de Telegram e Discord, mas NENHUM foi enviado a essas plataformas: não há token, não há bot criado e o adaptador que chama a API de verdade não foi escrito. Pedidos, estoque e usuários são fictícios.", "The code is bot.py ported to JavaScript and checked against recorded Python outputs. Events have the shape of Telegram and Discord ones, but NONE was sent to those platforms: there is no token, no bot created, and the adapter that calls the real API was not written. Orders, stock and users are fictional.")},
 "footer": B("Nada é enviado: tudo roda no seu navegador.", "Nothing is sent: everything runs in your browser."), "recorded": recorded}
finish(HERE, SLUG, cfg, logic, "Bot Telegram e Discord (demo)", "Demo interativa de um bot de atendimento para Telegram e Discord em modo demo, sem token.", ["bot.py"])
